input.script:
cutoff = time.parse("2026-06-03T00:00:00Z")

first = boundary retry 2 {
    return list_tickets({ page: 1, status: "open" })
} catch err {
    return fail("LIST_FAILED", err.code + ": " + err.message)
}

remaining = for page in list.range(2, first.total_pages + 1) {
    result = boundary retry 2 {
        return list_tickets({ page, status: "open" })
    } catch err {
        return fail("LIST_FAILED", err.code + ": " + err.message)
    }
    return result.items
}

all_open = fold acc = first.items for page in remaining { return acc + page }

escalated = for ticket in all_open {
    detail = boundary retry 2 {
        return get_ticket({ id: ticket.id })
    } catch err {
        return fail("GET_FAILED", err.code + ": " + err.message)
    }
    created_ms = time.parse(ticket.created_at)
    skip if created_ms >= cutoff
    body = detail.body if detail.body != null else ""
    skip if not ("refund" in text.lower(body))
    upd = boundary retry 2 {
        return update_ticket({ id: ticket.id, priority: "high", add_tags: ["billing-escalation"] })
    } catch err {
        return fail("UPDATE_FAILED", err.code + ": " + err.message)
    }
    return ticket.id
}

sub = submit_result({ answer: { escalated_ticket_ids: escalated } })
return { escalated, recorded: sub.recorded }
